INSERT INTO public.legal_documents(
  slug,title,version,locale,body_markdown,content_sha256,status,is_required,is_test_only
)
SELECT slug,title,version,locale,body_markdown,
  encode(extensions.digest(concat_ws(E'\n',slug,version,locale,title,body_markdown),'sha256'),'hex'),
  'draft',is_required,is_test_only
FROM (VALUES
('privacy-policy','Privacy Policy','0.1-dev','en-IN',convert_from(decode('','base64'),'UTF8'),true,true),
('terms-of-service','Terms of Service','0.1-dev','en-IN',convert_from(decode('','base64'),'UTF8'),true,true),
('data-processing-agreement','Data Processing Agreement','0.1-dev','en-IN',convert_from(decode('','base64'),'UTF8'),false,true)
) AS seed(slug,title,version,locale,body_markdown,is_required,is_test_only)
ON CONFLICT (slug,version,locale) DO NOTHING;